<script setup lang="ts">
import {onHide as onPageHide} from "@dcloudio/uni-app"
import {abandonLogin as cancelPageLogin} from "../../features/auth"
onPageHide(cancelPageLogin)

import LoginSheet from "../../components/LoginSheet.vue"

import { ref } from 'vue';import { onShow } from '@dcloudio/uni-app';import { request,navigate,type Row } from '../../api/platform'
const activities=ref<Row[]>([]),campaigns=ref<Row[]>([]),error=ref('')
onShow(async()=>{try{[activities.value,campaigns.value]=await Promise.all([request('GET','/api/v1/activities'),request('GET','/api/v1/review-campaigns')])}catch(e){error.value=(e as Error).message}})
</script>
<template><view class="page"><view class="hero-panel"><view class="hero"><text class="eyebrow">CAMPUS SERVICES</text><text class="title">校园服务</text><text class="subtitle">把报名、申报、资料和工具放在一个清晰入口。</text></view></view><view class="service-grid"><view class="service-tile" @click="navigate('activity-overview')"><text class="tile-icon">◎</text><text class="card-title">活动总览</text><text class="muted">全部活动与我的收藏</text></view><view class="service-tile" @click="navigate('resource')"><text class="tile-icon">▦</text><text class="card-title">资料与工具</text><text class="muted">考试日程、资料包、插件</text></view><view class="service-tile" @click="navigate('notifications')"><text class="tile-icon">◷</text><text class="card-title">强提醒</text><text class="muted">把重要节点加入日程</text></view></view><text class="error">{{ error }}</text><view class="section-head"><text class="section-title">正在开放的活动</text><text class="section-link">{{ activities.length }} 项</text></view><view v-for="a in activities" :key="a.id" class="card article-card" @click="navigate('activity','?id='+a.id)"><view class="meta-line"><text class="badge">活动报名</text><text class="small">剩余 {{ a.remaining }} 名额</text></view><text class="card-title">{{ a.title }}</text><text class="muted">{{ a.eventStart }}</text><text class="section-link" style="display:block;margin-top:11px">查看活动详情 →</text></view><view class="section-head"><text class="section-title">学生申报</text><text class="section-link">{{ campaigns.length }} 项</text></view><view v-for="c in campaigns" :key="c.id" class="card article-card" @click="navigate('review','?id='+c.id)"><view class="meta-line"><text class="badge">申报项目</text><text class="small">截止 {{ c.closeAt }}</text></view><text class="card-title">{{ c.title }}</text><text class="section-link" style="display:block;margin-top:11px">查看申报要求 →</text></view><view v-if="!activities.length&&!campaigns.length" class="empty">暂无开放项目</view><LoginSheet/></view></template>
